export async function goToNextSlide(page) {
    await page.getByRole("button", { name: "Next slide" }).click();
}

export async function goToPreviousSlide(page) {
    await page.getByRole("button", { name: "Previous slide" }).click();
}

export async function waitForAutoAdvanceWindow(page, waitMs) {
    await page.waitForTimeout(waitMs);
}
